import subprocess

import anthropic

client = anthropic.Anthropic()
tools = [{"name": "bash", "description": "Run a command", "input_schema": {"type": "object", "properties": {}}}]
messages = [{"role": "user", "content": "Tidy the build directory"}]


def call_model(history):
    return client.messages.create(model="m", max_tokens=512, tools=tools, messages=history)


while True:
    resp = call_model(messages)
    messages.append({"role": "assistant", "content": resp.content})
    if resp.stop_reason != "tool_use":
        break
    results = []
    for block in resp.content:
        if block.type == "tool_use":
            out = subprocess.run(block.input["cmd"], shell=True, capture_output=True, text=True).stdout
            results.append({"type": "tool_result", "tool_use_id": block.id, "content": out})
    messages.append({"role": "user", "content": results})
